const exact = new Text({ text: 'Exact area = 8/3 ≈ 2.667', color: YELLOW, fontSize: 22 });
exact.moveTo([4.3, -1.8, 0]);

let rectangles;
let estimateLabel;
function updateSum(n) {
  if (rectangles) scene.remove(rectangles);
  if (estimateLabel) scene.remove(estimateLabel);
  const dx = 2 / n;
  const pieces = [];
  let total = 0;
  for (let i = 0; i < n; i++) {
    const x0 = i * dx;
    const x1 = (i + 1) * dx;
    const mid = (x0 + x1) / 2;
    const height = mid * mid;
    total += height * dx;
    const box = new Polygon({
      vertices: [ax.c2p(x0, 0), ax.c2p(x1, 0), ax.c2p(x1, height), ax.c2p(x0, height)],
      color: BLUE
    });
    box.setFill(BLUE, 0.38);
    box.setStrokeWidth(1);
    pieces.push(box);
  }
  rectangles = new VGroup(...pieces);
  estimateLabel = new Text({ text: `n = ${n}    Estimate ≈ ${total.toFixed(4)}`, color: WHITE, fontSize: 22 });
